    const list='<div class="queuelist">'+rows.map(x=>'<button data-review-id="'+esc(x.id)+'" aria-pressed="'+(x.id===reviewId)+'"><b>'+esc(x.label||x.id)+'</b><small>'+esc(x.publisher||x.site_name||x.project_name||x.scope_type||'')+'</small>'+badge(x.review_status,x.review_status==='CONFLICT'?'bad':'dev')+'</button>').join('')+'</div>';
    const fieldLabels={raw_value:'원문 값',raw_unit:'단위',normalized_value_mw:'정규화 MW',raw_value_text:'추출 원문',normalized_value:'정규화 값',scope_type:'범위',capacity_stage:'용량 단계',measurement_basis:'측정 기준',source_grade:'근거 등급',published_at:'자료 발행일',publisher:'발행기관',site_name:'센터명',project_name:'프로젝트명',address_standard:'표준주소',planned_rfs_date:'예정 RFS',rfs_date:'실제 RFS',status_code:'단계',access_scope:'공개 범위'};
    const details=current?'<div class="pad"><div class="row">'+badge(current.review_status,'dev')+'<span class="sub">등록 '+date(current.created_at)+'</span></div><dl class="detailtable wide">'+Object.entries(current).filter(([k,v])=>!['id','label','review_status','created_at','can_publish'].includes(k)&&v!=null&&v!=='').map(([k,v])=>'<dt>'+esc(fieldLabels[k]||k)+'</dt><dd>'+(/url$/.test(k)?link(v):esc(typeof v==='object'?JSON.stringify(v):v))+'</dd>').join('')+'</dl></div><form class="reviewform" id="reviewForm"><label for="note">검토 사유</label><textarea id="note" required placeholder="확인한 원문과 승인·반려 판단 근거"></textarea>'+(current.can_publish?'<label class="publishlabel"><input type="checkbox" id="publish"> 승인과 동시에 공개 대상에 포함</label>':'')+'<div class="row wide"><button class="button primary" type="submit" data-decision="approve">승인</button><button class="button danger" type="button" id="reject">반려</button></div><p class="sub">승인은 선택 레코드의 검토 상태를 확정합니다. 추출 사실 승인만으로 다른 원장 필드가 자동 수정되지는 않습니다.</p><div id="reviewStatus" aria-live="polite"></div></form>':'<div class="empty">현재 유형에 검토 대기 항목이 없습니다.</div>';
    const audit=history.length?'<div class="wide">'+panel('최근 승인·반려 이력','<div class="tablewrap"><table><thead><tr><th>시간</th><th>유형</th><th>처리</th><th>검토자</th><th>판단 사유</th></tr></thead><tbody>'+history.slice(0,10).map(x=>'<tr><td>'+date(x.occurred_at)+'</td><td>'+esc(x.entity_type)+'</td><td>'+esc(x.action)+'</td><td>'+esc(x.actor_id)+'</td><td>'+esc(x.reason)+'</td></tr>').join('')+'</tbody></table></div>')+'</div>':'';
